/* Generate a VAPID key pair in a browser, with nothing installed.
 *
 * scripts/vapid-keys.mjs does the same thing and is nicer, but it needs Node.
 * This needs a browser you already have open, and is for whoever maintains
 * this site without a local development setup.
 *
 * HOW
 *   1. Open https://levlprep.com (it must be YOUR site, over https — the
 *      crypto this uses is unavailable on a plain http page or a blank tab).
 *   2. Press F12, then click the "Console" tab.
 *   3. Paste everything below, press Enter.
 *
 * Nothing is sent anywhere. The keys are generated by your own browser and
 * printed to your own console; no server, ours or anybody's, sees them.
 *
 * The PUBLIC key goes in two committed files. The PRIVATE key goes only into
 * Cloudflare, as a secret, and nowhere else — not in the repo, not in a chat,
 * not in a note synced to anything.
 *
 * Generate once. Replacing the pair later silently unsubscribes everyone who
 * ever agreed to notifications, and there is no way to ask them again.
 */
(async () => {
  const kp = await crypto.subtle.generateKey(
    { name: 'ECDSA', namedCurve: 'P-256' }, true, ['sign', 'verify']);
  const raw = await crypto.subtle.exportKey('raw', kp.publicKey);
  const jwk = await crypto.subtle.exportKey('jwk', kp.privateKey);
  const b64 = (b) => btoa(String.fromCharCode(...new Uint8Array(b)))
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

  const pub = b64(raw);
  const priv = jwk.d;

  // Prove the two halves belong together before printing them. A mismatched
  // pair fails later at the push service with a bare 401 and no explanation.
  const check = { kty: 'EC', crv: 'P-256', ext: true, d: priv,
    x: b64(new Uint8Array(raw).slice(1, 33)), y: b64(new Uint8Array(raw).slice(33, 65)) };
  try {
    const k = await crypto.subtle.importKey('jwk', check,
      { name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign']);
    await crypto.subtle.sign({ name: 'ECDSA', hash: 'SHA-256' }, k, new Uint8Array([1]));
  } catch (e) {
    console.error('The generated pair did not verify. Run this again.', e);
    return;
  }

  console.log('%cVAPID_PUBLIC_KEY  (goes in two committed files)', 'font-weight:bold');
  console.log(pub);
  console.log('%cVAPID_PRIVATE_KEY (goes ONLY into Cloudflare, as a secret)', 'font-weight:bold;color:#a83b2c');
  console.log(priv);
})();
